// A fake compiler extension exercising the public extension API (fixture).
const ID = '@znight/fake-http#'

/** @type {import('../../../../../../../src/index.ts').CompilerExtension} */
export default {
  apiVersion: 1,
  name: 'fake-http',
  decorators: {
    [`${ID}Controller`]: { targets: ['class'], params: ['static'] },
    [`${ID}Get`]: { targets: ['method'], params: ['static'] },
    [`${ID}Param`]: { targets: ['parameter'], params: ['static'] },
    [`${ID}UseGuard`]: { targets: ['class', 'method'], params: [], rest: 'value' },
    [`${ID}Settings`]: { targets: ['class'], params: [] },
    [`${ID}Value`]: { targets: ['property'], params: ['static'] },
  },
  analyzeClass(cls, ctx) {
    const controller = cls.decorators.find(d => d.identity === `${ID}Controller`)
    if (controller) {
      ctx.registerProvider(cls)
      const guards = cls.decorators
        .filter(d => d.identity === `${ID}UseGuard`)
        .flatMap(d => d.args)
        .map(arg => ctx.resolveClassRef(arg, { from: cls, role: 'guard' }))
        .filter(ref => ref !== undefined)
        .map(ref => ref.token)
      const routes = []
      for (const method of cls.methods) {
        const get = method.decorators.find(d => d.identity === `${ID}Get`)
        if (!get) continue
        routes.push({
          handler: method.name,
          path: get.args[0]?.value ?? '/',
          params: method.params.map(param => ({
            name: param.decorators.find(d => d.identity === `${ID}Param`)?.args[0]?.value,
            type: ctx.types.format(param.type),
          })),
        })
      }
      const context = ctx.bindInjection({ type: `${ID}HttpContext`, label: `http context of ${cls.displayName}` })
      const clock = ctx.bindInjection({ type: 'src/core/clock.ts#Clock' }, { from: cls })
      ctx.store({
        kind: 'controller',
        token: cls.identity,
        basePath: controller.args[0]?.value ?? '/',
        guards,
        routes,
        context: context.id,
        clock: clock.id,
      })
    }
    const settings = cls.decorators.find(d => d.identity === `${ID}Settings`)
    if (settings) {
      const keys = cls.properties
        .map(p => p.decorators.find(d => d.identity === `${ID}Value`)?.args[0]?.value)
        .filter(key => key !== undefined)
      ctx.registerProvider(cls, {
        factory: {
          deps: [{ type: '@znight/observability#Logger', label: `logger of ${cls.displayName}` }],
          generate: (g, input) => g.call(g.importFrom('@znight/fake-http', 'load'), [input.cls, input.deps[0]]),
        },
      })
      ctx.store({ kind: 'settings', token: cls.identity, keys })
    }
  },
  validate(ctx) {
    const controllers = ctx.stored.filter(data => data.kind === 'controller')
    const parts = controllers.map(data => {
      const context = ctx.binding({ id: data.context })
      const clock = ctx.binding({ id: data.clock })
      const provider = ctx.provider(data.token)
      return `${provider?.displayName}: context=${JSON.stringify(context)} clock=${JSON.stringify(clock)} guards=${data.guards.length}`
    })
    ctx.report({ code: 'ZNIGHT007', severity: 'warning', message: `fake-http validated ${parts.join('; ')}` })
  },
}
